INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1661121, 224657, 27991, '<td valign="top">nicely executed. the black and white really makes this look old time, 8</td>', 'nicely executed. the black and white really makes this look old time, 8', '2005-08-31 09:34:41.000000', NULL, 1),
(1661124, 223121, 15711, '<td valign="top">It has that Liliputian feel to it. I like the perspective and beautiful sky.</td>', 'It has that Liliputian feel to it. I like the perspective and beautiful sky.', '2005-08-31 09:35:35.000000', NULL, 1),
(1661127, 224845, 27991, '<td valign="top">the shoes are so dark.... i think this would have worked better without the bear as a distraction. however my three year old is getting a kick out of this pic.</td>', 'the shoes are so dark.... i think this would have worked better without the bear as a distraction. however my three year old is getting a kick out of this pic.', '2005-08-31 09:36:25.000000', NULL, 1),
(1661129, 224968, 42869, '<td valign="top">Too dark to see any detail</td>', 'Too dark to see any detail', '2005-08-31 09:36:40.000000', NULL, 1),
(1661133, 224391, 42869, '<td valign="top">Out of focus</td>', 'Out of focus', '2005-08-31 09:37:30.000000', NULL, 1),
(1661135, 223667, 15711, '<td valign="top">I like the grainy texture and the macro sense of it.  I used to wear mine til the rubber sole was off and I clunked around on straight wood.  Interesting take on the challenge. 7</td>', 'I like the grainy texture and the macro sense of it.  I used to wear mine til the rubber sole was off and I clunked around on straight wood.  Interesting take on the challenge. 7', '2005-08-31 09:37:33.000000', NULL, 1),
(1661136, 223643, 27991, '<td valign="top">shadows on the horses feet defeat this picture.... too bad the shadows were there... great idea.</td>', 'shadows on the horses feet defeat this picture.... too bad the shadows were there... great idea.', '2005-08-31 09:37:40.000000', NULL, 1),
(1661138, 224587, 42869, '<td valign="top">Nice angle</td>', 'Nice angle', '2005-08-31 09:37:55.000000', NULL, 1),
(1661140, 224772, 27991, '<td valign="top">THis is a nice photo however the mans pants drew my attention not the shoes.. i had to look for those. The shininess of the pants is overwhelming to the shoes.</td>', 'THis is a nice photo however the mans pants drew my attention not the shoes.. i had to look for those. The shininess of the pants is overwhelming to the shoes.', '2005-08-31 09:38:54.000000', NULL, 1),
(1661141, 223519, 15711, '<td valign="top">Cute. I like the angle of the feet.  The background is a tad distracting. I wonder if it would serve you better with a solid backdrop? You might lose the sense of outdoors, but I think it might work better - or at least it would for me. Hope this is helpful!!</td>', 'Cute. I like the angle of the feet.  The background is a tad distracting. I wonder if it would serve you better with a solid backdrop? You might lose the sense of outdoors, but I think it might work better - or at least it would for me. Hope this is helpful!!', '2005-08-31 09:38:54.000000', NULL, 1),
