(1664389, 223741, 35545, '<td valign="top">Good idea, well executed, but that bright patch in the center is distracting.</td>', 'Good idea, well executed, but that bright patch in the center is distracting.', '2005-08-31 23:25:04.000000', NULL, 1),
(1664391, 224611, 11295, '<td valign="top">That is one patient puppy. And nicly composed, well shot and the sepia works too. You get a 9... go give doggy a treat. :)</td>', 'That is one patient puppy. And nicly composed, well shot and the sepia works too. You get a 9... go give doggy a treat. :)', '2005-08-31 23:25:29.000000', NULL, 1),
