(1664546, 223654, 40703, '<td valign="top">I like this. Nice lighting. 7</td>', 'I like this. Nice lighting. 7', '2005-09-01 00:27:13.000000', NULL, 1),
(1664549, 224993, 40703, '<td valign="top">Very dark, but I can make it out. Nice idea. 6</td>', 'Very dark, but I can make it out. Nice idea. 6', '2005-09-01 00:28:01.000000', NULL, 1),
(1664551, 224279, 7485, '<td valign="top">Great idea, and the glowing yellow makes you really feel the overpowering heat. But wish more legs were visible, this barely qualifies as a herd!</td>', 'Great idea, and the glowing yellow makes you really feel the overpowering heat. But wish more legs were visible, this barely qualifies as a herd!', '2005-09-01 00:28:37.000000', NULL, 1),
