(1671221, 224645, 5112, '<td valign="top">Beautiful work!</td>', 'Beautiful work!', '2005-09-03 14:28:09.000000', NULL, 1),
(1671222, 224694, 33947, '<td valign="top">Very well lit and positioned. Nice composition and line. Love it! 10</td>', 'Very well lit and positioned. Nice composition and line. Love it! 10', '2005-09-03 14:28:41.000000', NULL, 1),
