(1673660, 223975, 40976, '<td valign="top">Hehe ... Nice job on uniqueness.  Lighting could be a tad bit brighter, but a good pic overall.</td>', 'Hehe ... Nice job on uniqueness.  Lighting could be a tad bit brighter, but a good pic overall.', '2005-09-04 21:09:21.000000', NULL, 1),
(1673661, 223802, 40976, '<td valign="top">Image is too dark.  I''d also encourage you to use the 640 pixels that are allowed.  :)</td>', 'Image is too dark.  I''d also encourage you to use the 640 pixels that are allowed.  :)', '2005-09-04 21:11:07.000000', NULL, 1),
(1673665, 223850, 34857, '<td valign="top">This was a potential t0''er, but a number of flaws keep is from succeding. The DOF, if a bit more deep, would maybe have been more effective. That, and Some detail/clarity seems to have been lost in the resize/resample.</td>', 'This was a potential t0''er, but a number of flaws keep is from succeding. The DOF, if a bit more deep, would maybe have been more effective. That, and Some detail/clarity seems to have been lost in the resize/resample.', '2005-09-04 21:12:58.000000', NULL, 1),
